using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a given query. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        // Uses the free DuckDuckGo Instant Answer API as a demo search provider.
        // Replace with Bing Search API, Google Custom Search, or another provider for production use.
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1";

        try
        {
            var response = await _httpClient.GetFromJsonAsync<DdgResponse>(url);
            var results = new List<SearchResult>();

            if (response is null)
                return results;

            // Include the abstract if available
            if (!string.IsNullOrWhiteSpace(response.Abstract))
            {
                results.Add(new SearchResult(
                    response.Heading ?? query,
                    response.AbstractUrl ?? "",
                    response.Abstract));
            }

            // Include related topics
            foreach (var topic in response.RelatedTopics ?? [])
            {
                if (results.Count >= maxResults)
                    break;

                if (!string.IsNullOrWhiteSpace(topic.Text))
                {
                    results.Add(new SearchResult(
                        topic.Text.Length > 80 ? topic.Text[..80] + "…" : topic.Text,
                        topic.FirstUrl ?? "",
                        topic.Text));
                }
            }

            if (results.Count == 0)
            {
                results.Add(new SearchResult(
                    $"Search results for: {query}",
                    $"https://duckduckgo.com/?q={encoded}",
                    $"No instant answer found. Try refining your query or searching directly at the URL above."));
            }

            return results;
        }
        catch (Exception ex)
        {
            return [new SearchResult("Error", "", $"Search failed: {ex.Message}. Try a different query.")];
        }
    }

    private sealed class DdgResponse
    {
        [JsonPropertyName("Abstract")]
        public string? Abstract { get; set; }

        [JsonPropertyName("AbstractUrl")]
        public string? AbstractUrl { get; set; }

        [JsonPropertyName("Heading")]
        public string? Heading { get; set; }

        [JsonPropertyName("RelatedTopics")]
        public List<DdgTopic>? RelatedTopics { get; set; }
    }

    private sealed class DdgTopic
    {
        [JsonPropertyName("Text")]
        public string? Text { get; set; }

        [JsonPropertyName("FirstURL")]
        public string? FirstUrl { get; set; }
    }
}

public sealed record SearchResult(string Title, string Url, string Snippet);

using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class NoteTool
{
    private readonly List<ResearchNote> _notes = [];

    public IReadOnlyList<ResearchNote> Notes => _notes;

    [Description("Save a research note with a topic label and the content you want to remember. Use this to record key findings as you research.")]
    public string SaveNote(
        [Description("A short topic label for the note (e.g. 'Definition', 'Key Stat', 'History')")] string topic,
        [Description("The note content — a fact, quote, or insight worth remembering")] string content,
        [Description("The source URL or reference for this note, if available")] string? source = null)
    {
        var note = new ResearchNote(topic, content, source, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved under '{topic}'.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public IReadOnlyList<ResearchNote> GetNotes()
    {
        return _notes;
    }

    [Description("Clear all saved research notes.")]
    public string ClearNotes()
    {
        var count = _notes.Count;
        _notes.Clear();
        return $"Cleared {count} note(s).";
    }
}

public sealed record ResearchNote(string Topic, string Content, string? Source, DateTime SavedAt);

