using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// --- Configuration ---
// Set your API key via environment variable: OPENAI_API_KEY
// Optionally set OPENAI_MODEL to override the default model.
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI (or compatible) API key.");
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tool instances ---
var webSearch = new WebSearchTool();
var noteTool = new NoteTool();

// --- Register AI services ---
builder.Services.AddChatClient(b => b
    .UseFunctionInvocation() // let the framework handle tool dispatch
    .Use(new OpenAIClient(apiKey).AsChatClient(modelId)));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// --- Build the agent ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
    AIFunctionFactory.Create(noteTool.ClearNotes),
};

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research assistant. Your job is to thoroughly research a topic the user provides.

        Workflow:
        1. Break the topic into 2-4 sub-questions worth investigating.
        2. Use the SearchWeb tool to find information for each sub-question.
        3. For every useful fact or insight you find, use SaveNote to record it with a topic label and source.
        4. After you have gathered enough notes (aim for at least 5), use GetNotes to review everything.
        5. Produce a final summary that synthesizes your notes into a clear, well-structured report
           with sections and source references.

        Be thorough but concise. Always cite your sources.
        """,
    Tools = tools,
};

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔍  AI Research Agent  🔍         ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var conversationHistory = new List<ChatMessage>();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine("Goodbye!");
        break;
    }

    conversationHistory.Add(new ChatMessage(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (the agent will search the web and take notes)");
    Console.ResetColor();

    try
    {
        var options = new AgentInvokeOptions { MaximumIterations = 15 };

        await foreach (var message in agent.InvokeStreamingAsync(
            conversationHistory, options, CancellationToken.None))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                Console.Write(message.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();

        // Show collected notes summary
        if (noteTool.Notes.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"[{noteTool.Notes.Count} research note(s) saved during this session]");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

